# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YAHUDİLİĞİN TEMEL KAVRAMLARI VE TARİHSEL DÖNEMLERİ</text>\n  <rect x="20" y="45" width="320" height="185" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">DÖRT TEMEL KAVRAM</text>\n  <rect x="35" y="78" width="290" height="138" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">1. İbrani: Göçebe / Nehrin ötesinden gelen (Hz. İbrahim)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">2. İsrail: Hz. Yakup\'un lakabı ve 12 kabile (Benî İsrâîl)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">3. Yahudi: Yahuda kabilesine ve krallığına mensup olan</text>\n  <text x="180" y="170" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">4. Musevi: Hz. Musa\'nın getirdiği şeriata bağlı olan</text>\n  <text x="180" y="198" text-anchor="middle" font-size="9.5" fill="#475569">İslam\'da: Hz. İbrahim, İshak, Yakup, Musa hak peygamberdir.</text>\n\n  <rect x="360" y="45" width="320" height="185" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">TARİHSEL KRONOLOJİ</text>\n  <rect x="375" y="78" width="290" height="138" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="520" y="96" text-anchor="middle" font-size="9.5" fill="#334155">• Atalar Dönemi: Hz. İbrahim, İshak, Yakup ve Yusuf</text>\n  <text x="520" y="116" text-anchor="middle" font-size="9.5" fill="#334155">• Çıkış (Exodus): Hz. Musa ile Mısır\'dan çıkış ve On Emir</text>\n  <text x="520" y="136" text-anchor="middle" font-size="9.5" fill="#334155">• Krallık: Hz. Davut ve Hz. Süleyman (I. Mabed\'in inşası)</text>\n  <text x="520" y="156" text-anchor="middle" font-size="9.5" fill="#334155">• Bölünme ve MÖ 587 Babil Sürgünü (I. Mabed\'in yıkılışı)</text>\n  <text x="520" y="176" text-anchor="middle" font-size="9.5" fill="#334155">• Pers Dönemi (II. Mabed) ve MS 70 Roma Yıkımı (Titus)</text>\n  <text x="520" y="196" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">• MS 70 Sonrası: Diaspora (Dağılma) ve Ağlama Duvarı</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YAHUDİ KUTSAL METİNLERİ: TANAH VE TALMUD YAPISI</text>\n  <rect x="20" y="45" width="360" height="175" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="200" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">1. YAZILI GELENEK: TANAH (TaNaH)</text>\n  <rect x="35" y="78" width="330" height="40" rx="6" fill="#ffffff" stroke="#6366f1" stroke-width="1.2"/>\n  <text x="200" y="94" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">T — Tora (Tevrat / 5 Kitap - Pentatök):</text>\n  <text x="200" y="110" text-anchor="middle" font-size="9.5" fill="#334155">Tekvin (Yaratılış), Çıkış, Levililer, Sayılar, Tesniye</text>\n  <rect x="35" y="124" width="330" height="40" rx="6" fill="#ffffff" stroke="#6366f1" stroke-width="1.2"/>\n  <text x="200" y="140" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">N — Neviim (Peygamberler):</text>\n  <text x="200" y="156" text-anchor="middle" font-size="9.5" fill="#334155">İlk ve Son Peygamberler (Yeşu, Hâkimler, Samuel, İşaya, Yeremya)</text>\n  <rect x="35" y="170" width="330" height="40" rx="6" fill="#ffffff" stroke="#6366f1" stroke-width="1.2"/>\n  <text x="200" y="186" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">K (H) — Ketuvim (Kitaplar / Yazılar):</text>\n  <text x="200" y="202" text-anchor="middle" font-size="9.5" fill="#334155">Mezmurlar (Zebur), Süleyman\'ın Özdeyişleri, Eyüp, Rut, Ester</text>\n\n  <rect x="395" y="45" width="285" height="175" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="537" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. SÖZLÜ GELENEK: TALMUD</text>\n  <rect x="410" y="80" width="255" height="55" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.2"/>\n  <text x="537" y="100" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">MİŞNA (Ana Sözlü Metin):</text>\n  <text x="537" y="116" text-anchor="middle" font-size="9.5" fill="#334155">MS 2. yüzyılda Haham Yehuda ha-Nasi</text>\n  <text x="537" y="129" text-anchor="middle" font-size="9.5" fill="#334155">tarafından derlenen sözlü yasalar.</text>\n  <rect x="410" y="145" width="255" height="62" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.2"/>\n  <text x="537" y="165" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">GEMARA (Yorum ve Şerh):</text>\n  <text x="537" y="181" text-anchor="middle" font-size="9.5" fill="#334155">Hahamların Mişna üzerindeki açıklamaları.</text>\n  <text x="537" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Mişna + Gemara = TALMUD</text>\n</svg>', '<svg viewBox="0 0 700 220" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="220" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YAHUDİLİKTE BAŞLICA SEMBOL VE UNSURLAR</text>\n  <rect x="20" y="48" width="210" height="152" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">MENORA VE MAGEN DAVİD</text>\n  <text x="125" y="96" text-anchor="middle" font-size="10" fill="#334155">• Menora: Yedi kollu şamdan;</text>\n  <text x="125" y="112" text-anchor="middle" font-size="10" fill="#334155">en eski kutsal semboldür.</text>\n  <text x="125" y="138" text-anchor="middle" font-size="10" fill="#334155">• Magen David: Altı köşeli</text>\n  <text x="125" y="154" text-anchor="middle" font-size="10" fill="#334155">Davut Yıldızı / Kalkanı.</text>\n  <text x="125" y="178" text-anchor="middle" font-size="10" fill="#334155">• Şofar: Koç boynuzu borusu.</text>\n\n  <rect x="245" y="48" width="210" height="152" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">İBADET KIYAFET VE OBJELERİ</text>\n  <text x="350" y="96" text-anchor="middle" font-size="10" fill="#334155">• Kipa: Başa takılan takke.</text>\n  <text x="350" y="118" text-anchor="middle" font-size="10" fill="#334155">• Tallit: Püsküllü dua şalı.</text>\n  <text x="350" y="140" text-anchor="middle" font-size="10" fill="#334155">• Tefilin: Alın ve kola bağlanan</text>\n  <text x="350" y="156" text-anchor="middle" font-size="10" fill="#334155">ayet yazılı deri kutucuklar.</text>\n  <text x="350" y="178" text-anchor="middle" font-size="10" fill="#334155">• Mezuza: Kapı pervazı kutusu.</text>\n\n  <rect x="470" y="48" width="210" height="152" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">MEKÂN VE GÜNLÜK KURALLAR</text>\n  <text x="575" y="96" text-anchor="middle" font-size="10" fill="#334155">• Sinagog / Havra: İbadet yeri.</text>\n  <text x="575" y="118" text-anchor="middle" font-size="10" fill="#334155">• Ağlama Duvarı: Batı Duvarı.</text>\n  <text x="575" y="140" text-anchor="middle" font-size="10" fill="#334155">• Şabat: Cumartesi dinlenme günü.</text>\n  <text x="575" y="162" text-anchor="middle" font-size="10" fill="#334155">• Kaşer (Koşer): Helal/uygun</text>\n  <text x="575" y="178" text-anchor="middle" font-size="10" fill="#334155">yiyecek-içecek kuralları.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
